<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Bouncing Ball Playground</title>
<style>
  body {
    background-color: #121212; /* Dark theme */
    color: #e0e0e0;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    margin: 0;
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 100vh;
    user-select: none;
  }

  .container {
    text-align: center;
    padding: 2rem;
    width: 100%;
    box-sizing: border-box;
  }

  canvas#sim {
    background-color: #1a1a1a; /* Slightly lighter than body */
    border-radius: 8px;
    border: 1px solid #333;
    display: block;
    margin-bottom: 2rem;
    box-shadow: inset 0 0 20px rgba(0,0,0,0.5); /* Inner depth */
    cursor: crosshair;

    /* Ensure size is at least 400x400 CSS pixels */
    width: max(400px, calc(100% - 2rem)); 
    aspect-ratio: 1 / 1;
  }

  .controls {
    display: flex;
    justify-content: center;
    gap: 1rem;
    margin-top: auto;
  }

  button {
    background-color: #3a3a3a;
    color: white;
    border: none;
    padding: 0.75rem 1.25rem;
    font-size: 1rem;
    font-weight: 600;
    cursor: pointer;
    border-radius: 4px;
    transition: background-color 0.2s ease, transform 0.1s ease;
    text-transform: uppercase;
    letter-spacing: 0.5px;
  }

  button:hover {
    background-color: #4a4a4a;
  }

  button:active {
    transform: scale(0.98);
    background-color: #333;
  }

  /* Specific Button Colors for better UX */
  #drop-btn { background-color: #2b5bbd !important; }
  #play-btn { background-color: #4a7c59 !important; }
  #clear-btn { background-color: #bd3131 !important; }

</style>
</head>
<body>

<div class="container">
    <canvas id="sim" width="600" height="600"></canvas>

    <div class="controls">
        <button id="drop-btn">Drop Ball</button>
        <button id="play-btn">Play/Pause</button>
        <button id="clear-btn">Clear All</button>
    </div>
</div>

<script>
(function() {
    const canvas = document.getElementById('sim');
    const ctx = canvas.getContext('2d', { alpha: false }); // Optimization

    // Configuration
    const GRAVITY = 0.6; 
    const RESTITUTION = 0.85; // Energy loss on bounce (must be < 1)

    let balls = [];
    let isRunning = true; 

    // Helper: Get random color for balls (Satisfying visual)
    function getRandomColor() {
        return `hsl(${Math.floor(Math.random() * 360)}, 70%, 50%)`;
    }

    class Ball {
        constructor(x, y, vx=0, vy=0, r) {
            this.x = x;
            this.y = y;
            this.vx = vx;
            this.vy = vy;
            this.r = Math.abs(r); 
            if (this.r < 5 || isNaN(this.r)) this.r = 10 + Math.random() * 20;
        }

        update(dt) {
            // Gravity accelerates downward
            this.vy += GRAVITY * dt;

            // Move
            this.x += this.vx * dt;
            this.y += this.vy * dt;

            // Collision: Floor
            if (this.y + this.r > canvas.height) {
                this.y = canvas.height - this.r; // Clamp inside
                this.vy *= -RESTITUTION;         // Reverse & dampen
            } 
            // Ceiling
            else if (this.y - this.r < 0) {
                this.y = this.r;                 // Clamp inside
                this.vy *= -RESTITUTION;
            }

            // Collision: Right Wall
            if (this.x + this.r > canvas.width) {
                this.x = canvas.width - this.r;  // Clamp inside
                this.vx *= -RESTITUTION;
            } 
            // Left Wall
            else if (this.x - this.r < 0) {
                this.x = this.r;                 // Clamp inside
                this.vx *= -RESTITUTION;
            }
        }

        draw(ctx) {
            ctx.beginPath();
            ctx.arc(this.x, this.y, this.r, 0, Math.PI * 2);

            const color = getRandomColor(); 
            ctx.fillStyle = color;

            // Add a glow effect for "satisfying" look
            ctx.shadowBlur = 15;
            ctx.shadowColor = 'rgba(255, 255, 255, 0.4)';

            ctx.fill();
            ctx.strokeStyle = '#fff'; // Highlight edge slightly
            ctx.lineWidth = 2;
            ctx.stroke();

            ctx.shadowBlur = 0;
        }
    }

    function updatePhysics(dt=1) {
        balls.forEach(ball => ball.update(dt));
    }

    function drawAll() {
        // Clear background
        ctx.fillStyle = '#1a1a1a'; 
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        balls.forEach(ball => ball.draw(ctx));
    }

    // API Implementation
    window.sim = {};

    // Canvas size properties (getters for dynamic accuracy)
    Object.defineProperty(window.sim, 'w', { get: () => canvas.width });
    Object.defineProperty(window.sim, 'h', { get: () => canvas.height });

    // Returns current balls array reference or copy?
    window.sim.balls = function() { return balls; };

    // Adds a ball at coordinates. Defaults vx=0, vy=0, r=randomish.
    window.sim.addBall = function(x, y, vx=0, vy=0, r) {
        balls.push(new Ball(x, y, vx, vy, r));
        drawAll();
    };

    // Removes all balls and redraws empty canvas.
    window.sim.clear = function() {
        balls = [];
        drawAll();
    };

    // Advances simulation one step (physics) and draws it.
    window.sim.step = function(dt=1) {
        updatePhysics(dt);
        drawAll();
    };

    // UI Interaction Logic

    // Play/Pause Toggle
    const playBtn = document.getElementById('play-btn');

    function loop() {
        if (!isRunning) return;
        window.sim.step(1);
        requestAnimationFrame(loop);
    }

    function togglePlay() {
        isRunning = !isRunning;
        if (isRunning && balls.length > 0) loop(); 
    }

    playBtn.addEventListener('click', () => {
        togglePlay();
    });

    // Drop Button -> Programmatic Add Ball (Random X, Top Y)
    document.getElementById('drop-btn').addEventListener('click', () => {
        const rX = Math.random() * (canvas.width - 40) + 20; 
        window.sim.addBall(rX, 50); 
    });

    // Clear Button -> Remove all balls
    document.getElementById('clear-btn').addEventListener('click', () => {
        window.sim.clear();
        isRunning = false; 
    });

    // Canvas Click Interaction -> Add ball at cursor (relative coordinates)
    canvas.addEventListener('click', (e) => {
        const rect = canvas.getBoundingClientRect();

        const scaleX = canvas.width / rect.width;
        const scaleY = canvas.height / rect.height;

        const x = (e.clientX - rect.left) * scaleX;
        const y = (e.clientY - rect.top) * scaleY;

        window.sim.addBall(x, y);
    });

})();
</script>
</body>
</html>
